PAGE = dict(
    slug='y_major_grid',
    title='Pane::y_major_grid',
    signature='Pane& Pane::y_major_grid(bool enable = true) noexcept',
    intro='Turns the major grid of the y axis on or off. The major grid is the set of lines drawn across the plot at the major tick positions of the y axis; it is off by default. `true` (the default argument) turns it on, `false` turns it off, and the state is stored in `y_axis().major_grid`. Turning it off again gives exactly the figure that never turned it on.\n\nThe two grids of an axis are independent: the minor grid can be on with the major grid off. Each axis has its own, and [`Pane::grid`](grid.md) sets all of them at once; [`Pane::grid_style`](grid_style.md) summarises the state of the whole pane as `None`, `Major` or `MajorMinor`. The call never throws and is read when the figure is rendered.',
    parameters='**enable** (`bool`, default `true`)\n    `true` draws the grid, `false` removes it.',
    returns='`Pane&`\n    The same pane, for chaining.',
    examples=[
        dict(id='readback', text='Off by default. `y_axis().major_grid` is false for a new axis; the call with no argument turns it on, `false` turns it off, and the last call wins.',
             code='auto fig = studio("y_major_grid_readback");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\nstd::cout << "new axis: " << pane.y_axis().major_grid << "\\n";\npane.y_major_grid();\nstd::cout << "after y_major_grid(): " << pane.y_axis().major_grid << "\\n";\npane.y_major_grid(false);\nstd::cout << "after y_major_grid(false): " << pane.y_axis().major_grid << "\\n";\npane.y_major_grid(true);\nfig.save_svg("figure.svg");'),
        dict(id='effect', text='The effect. Turning the major grid on adds grid lines to the figure, which can be counted as extra paths in the SVG; turning it off again restores the figure exactly.',
             code='auto build = [&](bool on) {\n  auto fig = studio("y_major_grid_effect");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\n  pane.y_major_grid(on);\n  return fig.to_svg();\n};\nauto paths = [](const std::string& svg) { std::size_t n = 0; for (auto at = svg.find("<path"); at != std::string::npos; at = svg.find("<path", at + 1)) ++n; return n; };\nstd::cout << "paths without: " << paths(build(false)) << ", with: " << paths(build(true)) << "\\n";\nstd::cout << "off again equals never set: " << (build(false) == build(false)) << "\\n";\nauto fig = studio("y_major_grid_effect_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_major_grid();\nfig.save_svg("figure.svg");'),
        dict(id='per_axis', text='Per axis. The y grid does not turn on the grid of the other axes, and each axis has its own switches.',
             code='auto fig = studio("y_major_grid_axes");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_major_grid();\nstd::cout << "x: " << pane.x_axis().major_grid << ", y: " << pane.y_axis().major_grid << ", z: " << pane.z_axis().major_grid << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='summary', text="The pane's grid summary. `Pane::grid_style()` reports `None` (0), `Major` (1) or `MajorMinor` (2) from the axis switches; the major grid of this axis moves it as shown.",
             code='auto fig = studio("y_major_grid_summary");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\nstd::cout << "no grid: " << static_cast<int>(pane.grid_style()) << "\\n";\npane.y_major_grid();\nstd::cout << "major on: " << static_cast<int>(pane.grid_style()) << "\\n";\npane.y_minor_grid();\nstd::cout << "major and minor on: " << static_cast<int>(pane.grid_style()) << "\\n";\npane.y_major_grid(true);\nfig.save_svg("figure.svg");'),
        dict(id='independent', text='Independent of the minor grid. The major grid can be on while the minor grid is off; the counts show how many paths each combination draws.',
             code='auto paths = [](const std::string& svg) { std::size_t n = 0; for (auto at = svg.find("<path"); at != std::string::npos; at = svg.find("<path", at + 1)) ++n; return n; };\nauto build = [&](bool major, bool minor) {\n  auto fig = studio("y_major_grid_independent");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\n  pane.y_major_grid(major).y_minor_grid(minor);\n  return fig.to_svg();\n};\nstd::cout << "none: " << paths(build(false, false)) << ", major only: " << paths(build(true, false)) << ", minor only: " << paths(build(false, true)) << ", both: " << paths(build(true, true)) << "\\n";\nauto fig = studio("y_major_grid_independent_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_major_grid().y_minor_grid();\nfig.save_svg("figure.svg");'),
    ],
    notes='- `noexcept`.\n- To turn the grid of every axis on or off in one call, use [`Pane::grid`](grid.md).',
    see=['[`Pane::y_minor_grid`](y_minor_grid.md): the minor grid of the same axis.', '[`Pane::grid`](grid.md): all axes at once.', '[`Pane::grid_style`](grid_style.md): the summary of the grid.', '[`Pane::x_major_grid`](x_major_grid.md): the same setting for the x axis.', '[`Pane::z_major_grid`](z_major_grid.md): the same setting for the z axis.'],
)
